import {esc,fmt} from '../../ui/format.js';
import {TYPES,FIELDS,PROCESS,POOLS,effective} from '../../core/model.js';
import {DIAGRAMS,expandedNeeds,modelAudit} from '../../core/mbse.js';
import {RELATIONS} from '../../core/model.js';
export function staffingView(ctx){const {m,result,baseline,search}=ctx;const n=id=>m.nodes.find(n=>n.id===id);return `<div class="panelhead"><div><h1>Utilaje & operatori</h1><p>Personal partajat, capacități și disponibilitate în același model.</p></div></div><div class="notice">Operatorul alocat unei mașini este rezervat pe întreg ciclul fiecărei operații care folosește mașina. Pentru încărcare/descărcare manuală și ciclu automat separat, modelează trei operații și alocă personal numai fazelor manuale. Competențele sunt descriptive, nu reguli automate de substituție.</div><div class="panel tablewrap"><table><thead><tr><th>Utilaj</th><th>Capacitate</th><th>Operatori / echipe</th><th></th></tr></thead><tbody>${m.nodes.filter(x=>['machine','robot','hardware','tool'].includes(x.type)).map(x=>`<tr><td>${esc(x.name)}</td><td>${effective(m,x).capacity}</td><td>${m.edges.filter(e=>e.type==='staffedBy'&&e.from===x.id).map(e=>`${esc(n(e.to).name)} ×${e.quantity} <button data-staffdelete="${esc(e.id)}">×</button>`).join('<br>')||'Fără personal alocat'}</td><td><button data-staff="${esc(x.id)}">Alocă operator</button></td></tr>`).join('')}</tbody></table></div><div class="panel"><h2>Necesar efectiv per operație</h2>${m.nodes.filter(x=>PROCESS.includes(x.type)).map(x=>`<p><b>${esc(x.name)}</b> → ${[...expandedNeeds(m,x)].map(([id,q])=>esc(n(id).name)+' ×'+q).join(', ')||'Nicio resursă'}</p>`).join('')}</div>`}
